#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long modPow(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long modInverse(long long a, long long m) {
    return modPow(a, m - 2);
}

